<script setup lang="ts">import { onMounted,ref } from 'vue';import { useRouter } from 'vue-router';import { useProfileStore } from '../stores/profile';import { useProjectStore } from '../stores/project';const router=useRouter(),store=useProfileStore(),cards=useProjectStore(),error=ref('');onMounted(async()=>{try{await store.restore();await store.publish();const cardId=localStorage.getItem('linkcard:pending-card');if(cardId){await cards.restore(cardId);await cards.attachProfile({id:store.profile.id,slug:store.profile.slug,published:true});localStorage.removeItem('linkcard:pending-card');setTimeout(()=>router.replace(`/cards/${cardId}/edit`),500)}else setTimeout(()=>router.replace('/dashboard'),500)}catch(e:any){error.value=e.message}})</script>
<template><div class="auth-callback"><div class="spinner">✳</div><h1>{{error?'Sign-in failed':'Publishing your profile…'}}</h1><p>{{error||'Securely connecting your account.'}}</p></div></template>

